MOTIF_NAME = 'opponent_cramped_interior_group'
MOTIF_DESCRIPTION = 'The evaluated side has a large interior opponent group with very few liberties surrounded by the evaluated side’s stones, indicating the opponent is trapped and dying.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    rows = 19
    cols = 19

    def neighbors4(r, c):
        for dr, dc in [(0,1),(1,0),(0,-1),(-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                yield nr, nc

    # Quick stone counts
    our_stones = 0
    opp_stones = 0
    for row in board_rows:
        for s in row:
            if s == color:
                our_stones += 1
            elif s == opp:
                opp_stones += 1
    if our_stones < 10 or opp_stones < 8:
        return False

    # Find opponent groups restricted to interior (rows 1..17, cols 1..17)
    visited = [[False]*cols for _ in range(rows)]
    max_opp_interior_size = 0
    min_opp_interior_libs = 999
    interior_opp_total = 0

    for r in range(1, 18):
        for c in range(1, 18):
            if board_rows[r][c] == opp and not visited[r][c]:
                stack = [(r,c)]
                visited[r][c] = True
                stones = 0
                libs = set()
                while stack:
                    cr, cc = stack.pop()
                    stones += 1
                    for nr, nc in neighbors4(cr, cc):
                        cell = board_rows[nr][nc]
                        if cell == '.':
                            libs.add((nr,nc))
                        elif cell == opp and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr,nc))
                interior_opp_total += stones
                if stones > max_opp_interior_size:
                    max_opp_interior_size = stones
                if len(libs) < min_opp_interior_libs:
                    min_opp_interior_libs = len(libs)

    # Need a meaty interior opponent group
    if max_opp_interior_size < 6:
        return False

    # Opponent interior groups must be cramped (few liberties)
    if min_opp_interior_libs > 2:
        return False

    # Count our stones adjacent to empty points that are inside opponent's interior area
    # Our stones on 3rd/4th line (influence) should be numerous
    our_influence = 0
    for r in range(rows):
        for c in range(cols):
            if board_rows[r][c] == color:
                dist = min(r, rows-1-r, c, cols-1-c)
                if 2 <= dist <= 3:
                    our_influence += 1

    if our_influence < 6:
        return False

    # The evaluated side should have more stones overall
    if our_stones < opp_stones:
        return False

    # Final check: the opponent's interior stones are a large fraction of their total
    if interior_opp_total < opp_stones * 0.4:
        return False

    return True

MOTIF_NAME = 'our_safe_3plus_liberty_groups_vs_opponent_single_liberty_dead'
MOTIF_DESCRIPTION = 'The evaluated side has at least 6 groups with 3 or more liberties (safe), while the opponent has at least 2 groups with exactly 1 liberty (dead), indicating a large life-and-death imbalance favoring the evaluated side.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    rows = 19
    cols = 19
    DIRS = [(0,1),(1,0),(0,-1),(-1,0)]

    def neighbors4(r, c):
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                yield nr, nc

    our_total = sum(1 for row in board_rows for s in row if s == color)
    opp_total = sum(1 for row in board_rows for s in row if s == opp)
    if our_total < 12 or opp_total < 6:
        return False

    visited = [[False]*cols for _ in range(rows)]
    our_safe = 0
    opp_dead = 0

    for r in range(rows):
        for c in range(cols):
            stone = board_rows[r][c]
            if stone in (color, opp) and not visited[r][c]:
                stack = [(r,c)]
                visited[r][c] = True
                cells = []
                libs = set()
                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr,cc))
                    for nr, nc in neighbors4(cr, cc):
                        cell = board_rows[nr][nc]
                        if cell == stone and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr,nc))
                        elif cell == '.':
                            libs.add((nr,nc))
                if stone == color:
                    if len(libs) >= 3:
                        our_safe += 1
                else:
                    if len(libs) == 1:
                        opp_dead += 1

    return our_safe >= 6 and opp_dead >= 2

MOTIF_NAME = 'third_fourth_line_dominance'
MOTIF_DESCRIPTION = 'The evaluated side has many more stones on the 3rd and 4th lines from the edge than on the 1st and 2nd lines, indicating strong outward influence and territory potential.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    rows = 19
    cols = 19

    # Count stones by distance from nearest edge
    our_stones = 0
    opp_stones = 0
    our_3_4 = 0  # 3rd and 4th line
    our_1_2 = 0  # 1st and 2nd line
    opp_3_4 = 0
    opp_1_2 = 0

    for r in range(rows):
        for c in range(cols):
            s = board_rows[r][c]
            if s == '.':
                continue
            # Manhattan distance to nearest edge
            dist = min(r, rows-1-r, c, cols-1-c)
            if s == color:
                our_stones += 1
                if dist == 2 or dist == 3:
                    our_3_4 += 1
                elif dist == 0 or dist == 1:
                    our_1_2 += 1
            else:
                opp_stones += 1
                if dist == 2 or dist == 3:
                    opp_3_4 += 1
                elif dist == 0 or dist == 1:
                    opp_1_2 += 1

    if our_stones < 12 or opp_stones < 8:
        return False

    # Winning side has good 3rd/4th line presence and not too many 1st/2nd line stones
    if our_3_4 < 8:
        return False
    if our_1_2 > our_3_4 * 0.7:
        return False

    # We should dominate 3rd/4th line relative to opponent
    if our_3_4 < opp_3_4 + 3:
        return False

    # Opponent shouldn't dominate us on 3rd/4th
    if opp_3_4 > our_3_4:
        return False

    # Our 3rd/4th vs opponent's 1st/2nd ratio should be good
    return our_3_4 >= opp_1_2 + 5

MOTIF_NAME = 'our_anchored_groups_vs_opponent_floating'
MOTIF_DESCRIPTION = 'The evaluated side has at least 4 groups with 3+ liberties touching lines 1-3 (anchored), while opponent has at least 2 central groups (no stone below row 3 or above row 15) with at most 2 liberties, indicating territorial security against weak floating opponent.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    rows = 19
    cols = 19

    def neighbors4(r, c):
        for dr, dc in [(0,1),(1,0),(0,-1),(-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                yield nr, nc

    our_total = sum(1 for row in board_rows for s in row if s == color)
    opp_total = sum(1 for row in board_rows for s in row if s == opp)
    if our_total < 10 or opp_total < 6:
        return False

    visited = [[False]*cols for _ in range(rows)]
    our_anchored = 0
    opp_floating_weak = 0

    for r in range(rows):
        for c in range(cols):
            stone = board_rows[r][c]
            if stone in (color, opp) and not visited[r][c]:
                stack = [(r,c)]
                visited[r][c] = True
                cells = []
                libs = set()
                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr,cc))
                    for nr, nc in neighbors4(cr, cc):
                        cell = board_rows[nr][nc]
                        if cell == stone and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr,nc))
                        elif cell == '.':
                            libs.add((nr,nc))
                if stone == color:
                    if len(libs) >= 3:
                        touches_low = any(gr <= 2 or gr >= 16 or gc <= 2 or gc >= 16 for (gr, gc) in cells)
                        if touches_low and len(cells) >= 3:
                            our_anchored += 1
                else:
                    if len(libs) <= 2:
                        is_central = all(3 <= gr <= 15 and 3 <= gc <= 15 for (gr, gc) in cells)
                        if is_central and len(cells) >= 2:
                            opp_floating_weak += 1

    return our_anchored >= 4 and opp_floating_weak >= 2

MOTIF_NAME = 'our_large_stable_groups_vs_opponent_small_weak_groups'
MOTIF_DESCRIPTION = 'The evaluated side has at least one group of 10+ stones with 5+ liberties (large and stable), while the opponent has at least 3 groups of 2-5 stones with at most 2 liberties (small and weak), indicating a strong territorial foundation against crumbling opposition.'
def motif(board_rows: list[str], color: str) -> bool:
    opp = 'W' if color == 'B' else 'B'
    rows = 19
    cols = 19
    DIRS = [(0,1),(1,0),(0,-1),(-1,0)]

    def neighbors4(r, c):
        for dr, dc in DIRS:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                yield nr, nc

    our_total = sum(1 for row in board_rows for s in row if s == color)
    opp_total = sum(1 for row in board_rows for s in row if s == opp)
    if our_total < 15 or opp_total < 10:
        return False

    visited = [[False]*cols for _ in range(rows)]
    has_large_stable = False
    opp_small_weak = 0

    for r in range(rows):
        for c in range(cols):
            stone = board_rows[r][c]
            if stone in (color, opp) and not visited[r][c]:
                stack = [(r,c)]
                visited[r][c] = True
                cells = []
                libs = set()
                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr,cc))
                    for nr, nc in neighbors4(cr, cc):
                        cell = board_rows[nr][nc]
                        if cell == stone and not visited[nr][nc]:
                            visited[nr][nc] = True
                            stack.append((nr,nc))
                        elif cell == '.':
                            libs.add((nr,nc))
                sz = len(cells)
                lc = len(libs)
                if stone == color:
                    if sz >= 10 and lc >= 5:
                        has_large_stable = True
                else:
                    if 2 <= sz <= 5 and lc <= 2:
                        opp_small_weak += 1

    return has_large_stable and opp_small_weak >= 3
